const $=s=>document.querySelector(s);const $$=s=>Array.from(document.querySelectorAll(s));
const PAGE={command:['Home / Command Center','Live overview, home requirements, customer status and alert summary.'],fleet:['Machine Fleet','Correct client count from live latest table; no fake machines.'],machine360:['Machine 360','Complete machine story: CPU, RAM, disk, GPU, USB, network, software and inventory sync.'],network:['Network + VPN','Machine-wise IP, MAC, adapters, gateway, DNS, VPN, ISP, latency, jitter and speed.'],hardware:['Hardware Intelligence','CPU/RAM/SSD/HDD/NVMe/GPU details from live client payload and API normalizer.'],software:['Software Intelligence','Installed software from live payload plus software register.'],hwInventory:['Hardware Asset Register','Inventory, Add/Edit/Delete, warranty, invoice, vendor, serial and sync.'],swInventory:['Software Asset Register','Software/license register and live installed apps.'],isoAudit:['ISO Audit Center','Missing fields, unmatched assets and audit-ready output.'],usb:['USB + Peripherals','Keyboard, mouse, headset, USB storage and peripheral changes.'],changes:['Human Change Log','Machine-wise and day-wise meaningful changes.'],history:['Day History','Fast summary view, no heavy heartbeat sample loading by default.'],messages:['Client Messages','Send messages and see sent history.'],notifications:['Notifications','Active/off/locked rules and alert history.'],deploy:['Deploy Center','Correct install/update commands. No wrong placeholder.'],settings:['Settings','Editable organization name, logo, login background photo, users/roles/retention rules.']};
let S={status:null,branding:{},machines:[],machine360:null,hw:{rows:[],total:0},sw:{rows:[],count:0},rules:[],alerts:[],deploy:[],iso:null,messages:[],history:null,selected:null,lastError:null,pages:{},activeTab:'command'};
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function n(v){return (v===undefined||v===null||v===''||v===0||v==='0')?'Not reported':v}
function toast(m){const t=$('#toast');t.textContent=m;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),4500)}
function pill(v,type=''){return `<span class="pill ${type}">${esc(v)}</span>`}
function empty(m){return `<div class="empty">${esc(m)}</div>`}
function creatorFooter(){return `<div class="signature-footer">Created by <b>Sagar Kerhalkar</b> · Contact: <b>8105977226</b> · Profile: <a href="https://sagarkerhalkar.com" target="_blank">sagarkerhalkar.com</a></div>`}
function kv(obj){return `<div class="table-wrap"><table><tbody>${Object.entries(obj||{}).map(([k,v])=>`<tr><th>${esc(k)}</th><td>${Array.isArray(v)||typeof v==='object'?`<pre class="code">${esc(JSON.stringify(v,null,2))}</pre>`:esc(n(v))}</td></tr>`).join('')}</tbody></table></div>`}
function pagedTable(id, rows, cols, pageSize=20){rows=rows||[];if(!rows.length)return empty('No rows from live API.');cols=cols||Object.keys(rows[0]||{}).slice(0,12);const total=rows.length;const pages=Math.max(1,Math.ceil(total/pageSize));let p=S.pages[id]||0;if(p>=pages)p=pages-1;if(p<0)p=0;S.pages[id]=p;const start=p*pageSize;const slice=rows.slice(start,start+pageSize);return `<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${slice.map(r=>`<tr>${cols.map(c=>`<td>${esc(n(r?.[c]))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="pagebar"><span>Showing ${start+1}-${Math.min(start+pageSize,total)} of ${total} · page ${p+1}/${pages}</span><span><button class="page-btn" onclick="pageTable('${id}',-1)">Prev</button><button class="page-btn" onclick="pageTable('${id}',1)">Next</button></span></div>`}
function pageTable(id,delta){S.pages[id]=(S.pages[id]||0)+delta;renderAll();switchTab(S.activeTab,true)}
async function api(path,opt={}){const res=await fetch(path,{cache:'no-store',headers:{'Content-Type':'application/json'},...opt});const txt=await res.text();let data={};try{data=txt?JSON.parse(txt):{}}catch(e){throw new Error(`${path} returned non-json: ${txt.slice(0,160)}`)}if(!res.ok)throw new Error(data.error||res.statusText);return data}
async function tryApi(path,opt){try{return await api(path,opt)}catch(e){return {ok:false,error:e.message}}}
function setApiStatus(ok,msg){const el=$('#apiStatus');el.classList.toggle('good',!!ok);el.classList.toggle('bad',!ok);el.lastChild.nodeValue=' '+msg}
function orgName(){return (S.branding?.company_name||'Sagar').trim()||'Sagar'}
function appTitle(){return S.branding?.app_title||'System Health Monitor V10'}
function applyBranding(){const b=S.branding||{};$('#heroCompany').textContent=orgName();$('#heroTitle').textContent=appTitle()+' · logo and organization name editable from Settings.';$('#sideOrgName').textContent=orgName();if(b.logo_path){$('#brandLogo').src=b.logo_path;$('#topLogo').src=b.logo_path}if(b.login_photo_path){document.documentElement.style.setProperty('--login-bg',`url('${b.login_photo_path}')`)}document.title=orgName()+' · V10 System Health Monitor'}
