function switchTab(tab,silent=false){S.activeTab=tab;$$('.tab').forEach(t=>t.classList.remove('show'));$('#'+tab)?.classList.add('show');$$('.nav').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));const [t,s]=PAGE[tab]||['V10',''];$('#pageTitle').textContent=t;$('#pageSubTitle').textContent=s;if(!silent)window.scrollTo({top:0,behavior:'smooth'})}
