function rowsToCsv(rows){
  rows=rows||[]; if(!rows.length) return 'message\nNo rows';
  const cols=[]; rows.forEach(r=>Object.keys(r||{}).forEach(k=>{if(!cols.includes(k))cols.push(k)}));
  const escCsv=v=>'"'+String(v??'').replace(/"/g,'""').replace(/\r?\n/g,' ')+'"';
  return cols.join(',')+'\n'+rows.map(r=>cols.map(c=>escCsv(r?.[c])).join(',')).join('\n');
}
function downloadCsvLocal(name,rows){
  const blob=new Blob([rowsToCsv(rows)],{type:'text/csv;charset=utf-8'});
  const url=URL.createObjectURL(blob); const a=document.createElement('a'); a.href=url; a.download=name; a.click(); setTimeout(()=>URL.revokeObjectURL(url),1500);
}
function parseCsvText(text){
  const lines=String(text||'').replace(/^\uFEFF/,'').split(/\r?\n/).filter(x=>x.trim());
  if(!lines.length)return [];
  function parseLine(line){const out=[];let cur='',q=false;for(let i=0;i<line.length;i++){const ch=line[i];if(ch==='"'){if(q&&line[i+1]==='"'){cur+='"';i++;}else q=!q;}else if(ch===','&&!q){out.push(cur);cur='';}else cur+=ch;}out.push(cur);return out;}
  const header=parseLine(lines[0]).map(x=>x.trim());
  return lines.slice(1).map(line=>{const vals=parseLine(line);const r={};header.forEach((h,i)=>r[h]=vals[i]??'');return r;});
}
function isOnline(m){return String(m?.online_status||m?.status||m?.online||'').toLowerCase().includes('online') || m?.online===true || m?.is_online===true}
function hasIssue(m){const cpu=Number(m?.cpu_percent||0), ram=Number(m?.ram_percent||0), disk=Number(m?.disk_max_percent||0);return !isOnline(m)||cpu>=90||ram>=90||disk>=90||String(m?.attention||m?.issue||'').trim()!==''}
function normalizeMachineRows(){return (S.machines||[]).map(m=>({...m,_issue:hasIssue(m)?'YES':'NO',_online:isOnline(m)?'online':'offline'}));}
