function ispLiveSummary(){
  const m=S.machine360||{};const n1=m.network||{};const pub=n1.public_internet||m.public_internet||S.status?.public_internet||{};
  return {
    isp:n(pub.isp||n1.isp||S.status?.isp), public_ip:n(pub.public_ip||n1.public_ip),
    download:n(n1.current_download_mbps||n1.download_mbps||S.status?.current_download_mbps),
    upload:n(n1.current_upload_mbps||n1.upload_mbps||S.status?.current_upload_mbps),
    latency:n(n1.latency_ms||S.status?.latency_ms), jitter:n(n1.jitter_ms||S.status?.jitter_ms), loss:n(n1.packet_loss_percent||S.status?.packet_loss_percent)
  }
}
