async function saveRuleFromRow(id){const enabled=document.querySelector(`#rule_en_${CSS.escape(id)}`)?.checked?1:0;const threshold=document.querySelector(`#rule_th_${CSS.escape(id)}`)?.value;try{await api('/api/v10final/notifications/rules/save',{method:'POST',body:JSON.stringify({id,enabled,threshold})});toast('Rule saved: '+id);await loadNotifications();renderNotifications()}catch(e){toast('Rule save failed: '+e.message)}}
function renderNotifications(){
  const rows=(S.rules||[]);
  const html=rows.map(r=>`<tr><td>${esc(r.id)}</td><td>${esc(r.name||r.title||r.id)}</td><td><input id="rule_en_${esc(r.id)}" type="checkbox" ${Number(r.enabled)?'checked':''} ${['cpu_high','ram_high'].includes(r.id)?'disabled':''}></td><td><input id="rule_th_${esc(r.id)}" value="${esc(r.threshold||'')}" ${['cpu_high','ram_high'].includes(r.id)?'disabled':''}></td><td>${['cpu_high','ram_high'].includes(r.id)?'LOCKED OFF':'Admin editable'}</td><td><button class="page-btn" onclick="saveRuleFromRow('${esc(r.id)}')">Save</button></td></tr>`).join('');
  $('#notifications').innerHTML=`<div class="grid"><div class="panel wide"><h3>Notifications</h3><p class="compact-note">Active/off/locked rules. Admin can edit normal rules. CPU-only and RAM-only stay locked unless super admin.</p><div class="table-wrap small-scroll"><table><thead><tr><th>Rule</th><th>Name</th><th>Active</th><th>Threshold</th><th>Lock</th><th>Action</th></tr></thead><tbody>${html}</tbody></table></div></div><div class="panel wide"><h3>Alert History</h3>${renderAlerts(200)}</div></div>${creatorFooter()}`
}
async function saveDeployProfile(){const body={name:$('#depName').value,os_type:$('#depOs').value,command:$('#depCmd').value,test_command:$('#depTest').value,troubleshooting:$('#depTrouble').value,message:$('#depMsg').value,enabled:1};try{await api('/api/v10final/deploy/profiles/save',{method:'POST',body:JSON.stringify(body)});toast('Deploy profile saved');await loadDeploy();renderDeploy()}catch(e){toast('Deploy save failed: '+e.message)}}
function renderDeploy(){const server=location.origin;$('#deploy').innerHTML=`<div class="grid"><div class="panel wide"><h3>Deploy Center</h3><p class="compact-note">Real Windows/Ubuntu install and update commands. No wrong SERVER_IP placeholder. You can edit command, test command, troubleshooting and message column.</p>${pagedTable('deploy4',S.deploy,['name','os_type','command','test_command','troubleshooting','message','notes','enabled'],8)}</div><div class="panel half"><h3>Windows Install / Update</h3><pre class="code">mkdir C:\\Temp -Force\niwr "${server}/scripts/BOOTSTRAP_WINDOWS_CLIENT_2294.ps1" -OutFile C:\\Temp\\BOOTSTRAP_WINDOWS_CLIENT_2294.ps1\npowershell -ExecutionPolicy Bypass -File C:\\Temp\\BOOTSTRAP_WINDOWS_CLIENT_2294.ps1 -ServerUrl ${server} -IntervalSeconds 5</pre></div><div class="panel half"><h3>Ubuntu Install / Update</h3><pre class="code">curl -fsSL ${server}/scripts/BOOTSTRAP_UBUNTU_CLIENT_2294.sh -o /tmp/bootstrap_v10.sh\nsudo bash /tmp/bootstrap_v10.sh --server-url ${server} --interval 5</pre></div><div class="panel wide"><h3>Add / Edit Deploy Command</h3><div class="form-grid"><input id="depName" placeholder="Profile name"><select id="depOs"><option>windows</option><option>ubuntu</option></select><input id="depCmd" placeholder="Main install/update command"><input id="depTest" placeholder="Test command"><input id="depTrouble" placeholder="Troubleshooting command"><input id="depMsg" placeholder="Message / note to show"></div><button class="primary" onclick="saveDeployProfile()">Save Deploy Profile</button></div></div>${creatorFooter()}`}
